	public void Evt_UnitStatePredic_Invoke(EBGUUnitState UnitState, bool NeedForceUpdate = false, float Time = -1f)
	{
		if (GetOwner().GetLocalRole() == ENetRole.ROLE_SimulatedProxy || BGUFunctionLibraryCS.IsRemoteControlPawn(GetOwner()))
		{
			return;
		}
		if (base.HasAuthority)
		{
			Evt_UnitStatePredicMultiCast(UnitState, NeedForceUpdate, Time);
			return;
		}
		GSPredictionKey gSPredictionKey = null;
		int predictionKeyId = -1;
		int parentPredictionKeyId = -1;
		if (BGUFunctionLibraryCS.IsLocalControlPawn(GetOwner()) && !base.HasAuthority)
		{
			gSPredictionKey = BGS_EventCollectionCS.Get(GetOwner())?.Evt_BGS_AllocPredictionKey.Invoke();
			if (gSPredictionKey != null)
			{
				predictionKeyId = gSPredictionKey.Id;
				parentPredictionKeyId = gSPredictionKey.ParentId;
			}
			BGS_EventCollectionCS.Get(GetOwner())?.Evt_BGS_BeginPredictionScope.Invoke(EPredictionState.ClientPredicting, BGC_PredictionKeyData.sPredictableFunctionCache["BUS_GSEventCollection:Evt_UnitStatePredicMultiCast"], gSPredictionKey.Id);
			Evt_UnitStatePredic.PredictInvoke(UnitState, NeedForceUpdate, Time, gSPredictionKey);
			BGS_EventCollectionCS.Get(GetOwner())?.Evt_BGS_EndPredictionScope.Invoke();
		}
		Evt_UnitStatePredicServer(UnitState, NeedForceUpdate, Time, predictionKeyId, parentPredictionKeyId);
	}

