	public void Evt_SmartCastSkillTry_Invoke(int ID, List<int> RuleIDList, EMontageBindReason Reason = EMontageBindReason.Default, ESkillDirection SkillDirection = ESkillDirection.None, bool bNeedCheckSkillCanCast = true, ECastSkillSourceType SourceType = ECastSkillSourceType.SmartCastSkill)
	{
		if (GetOwner().GetLocalRole() == ENetRole.ROLE_SimulatedProxy || BGUFunctionLibraryCS.IsRemoteControlPawn(GetOwner()))
		{
			return;
		}
		if (base.HasAuthority)
		{
			Evt_SmartCastSkillTryMultiCast(ID, RuleIDList, Reason, SkillDirection, bNeedCheckSkillCanCast, SourceType);
			return;
		}
		GSPredictionKey gSPredictionKey = null;
		int predictionKeyId = -1;
		int parentPredictionKeyId = -1;
		if (BGUFunctionLibraryCS.IsLocalControlPawn(GetOwner()) && !base.HasAuthority)
		{
			gSPredictionKey = BGS_EventCollectionCS.Get(GetOwner())?.Evt_BGS_AllocPredictionKey.Invoke();
			if (gSPredictionKey != null)
			{
				predictionKeyId = gSPredictionKey.Id;
				parentPredictionKeyId = gSPredictionKey.ParentId;
			}
			BGS_EventCollectionCS.Get(GetOwner())?.Evt_BGS_BeginPredictionScope.Invoke(EPredictionState.ClientPredicting, BGC_PredictionKeyData.sPredictableFunctionCache["BUS_GSEventCollection:Evt_SmartCastSkillTryMultiCast"], gSPredictionKey.Id);
			Evt_SmartCastSkillTry.PredictInvoke(ID, RuleIDList, Reason, SkillDirection, bNeedCheckSkillCanCast, SourceType, gSPredictionKey);
			BGS_EventCollectionCS.Get(GetOwner())?.Evt_BGS_EndPredictionScope.Invoke();
		}
		Evt_SmartCastSkillTryServer(ID, RuleIDList, Reason, SkillDirection, bNeedCheckSkillCanCast, SourceType, predictionKeyId, parentPredictionKeyId);
	}

