	public void Evt_ClientMultiCastRPCTest2_Invoke(UAnimMontage Montage, float PlayTimeRate, float MontagePosOffset, FName StartSectionName, EMontageBindReason Reason = EMontageBindReason.Default)
	{
		if (base.HasAuthority)
		{
			Evt_ClientMultiCastRPCTest2MultiCast(Montage, PlayTimeRate, MontagePosOffset, StartSectionName, Reason);
			return;
		}
		GSPredictionKey gSPredictionKey = null;
		int predictionKeyId = -1;
		int parentPredictionKeyId = -1;
		if (PredictionKeyData.ServerRecvingOrClientCueing())
		{
			return;
		}
		APawn controlledPawn = UGSE_EngineFuncLib.GetFirstLocalPlayerController(GetOwner()).GetControlledPawn();
		BGUPlayerCharacterCS bGUPlayerCharacterCS = GetOwner() as BGUPlayerCharacterCS;
		if (base.IsServer || !(bGUPlayerCharacterCS != null) || !(bGUPlayerCharacterCS != controlledPawn))
		{
			gSPredictionKey = BGS_EventCollectionCS.Get(GetOwner())?.Evt_BGS_AllocPredictionKey.Invoke();
			if (gSPredictionKey != null)
			{
				predictionKeyId = gSPredictionKey.Id;
				parentPredictionKeyId = gSPredictionKey.ParentId;
			}
			BGS_EventCollectionCS.Get(GetOwner())?.Evt_BGS_BeginPredictionScope.Invoke(EPredictionState.ClientPredicting, BGC_PredictionKeyData.sPredictableFunctionCache["BUS_GSEventCollection:Evt_ClientMultiCastRPCTest2MultiCast"], gSPredictionKey.Id);
			Evt_ClientMultiCastRPCTest2.PredictInvoke(Montage, PlayTimeRate, MontagePosOffset, StartSectionName, Reason, gSPredictionKey);
			BGS_EventCollectionCS.Get(GetOwner())?.Evt_BGS_EndPredictionScope.Invoke();
			if (controlledPawn == GetOwner())
			{
				Evt_ClientMultiCastRPCTest2Server(Montage, PlayTimeRate, MontagePosOffset, StartSectionName, Reason, predictionKeyId, parentPredictionKeyId);
			}
			else if (base.IsServer)
			{
				Evt_ClientMultiCastRPCTest2SPTransmitServer(Montage, PlayTimeRate, MontagePosOffset, StartSectionName, Reason, predictionKeyId, parentPredictionKeyId, UGSE_EngineFuncLib.GetFirstLocalPlayerController(GetOwner()).PlayerState);
			}
			else if (controlledPawn != null)
			{
				BUS_EventCollectionCS.Get(controlledPawn)?.Evt_ClientMultiCastRPCTest2SPTransmitServer(Montage, PlayTimeRate, MontagePosOffset, StartSectionName, Reason, predictionKeyId, parentPredictionKeyId, GetOwner());
			}
		}
	}

