			BGS_EventCollectionCS.Get(GetOwner())?.Evt_BGS_BeginPredictionScope.Invoke(EPredictionState.ServerRecving, BGC_PredictionKeyData.sPredictableFunctionCache["BUS_GSEventCollection:Evt_TestPredictMultiCast"], -1, playerState);
