			BGS_EventCollectionCS.Get(GetOwner())?.Evt_BGS_EndPredictionScope.Invoke();
			if (controlledPawn == GetOwner())
			{
				Evt_TriggerSkillEffect_TransmitServer(EffectID, EffectInstReq, InnerTarget, bWithRPCEvent, predictionKeyId, parentPredictionKeyId);
			}
			else if (base.IsServer)
			{
				Evt_TriggerSkillEffect_TransmitSPTransmitServer(EffectID, EffectInstReq, InnerTarget, bWithRPCEvent, predictionKeyId, parentPredictionKeyId, UGSE_EngineFuncLib.GetFirstLocalPlayerController(GetOwner()).PlayerState);
			}
			else if (controlledPawn != null)
			{
				BUS_EventCollectionCS.Get(controlledPawn)?.Evt_TriggerSkillEffect_TransmitSPTransmitServer(EffectID, EffectInstReq, InnerTarget, bWithRPCEvent, predictionKeyId, parentPredictionKeyId, GetOwner());
			}
		}
	}

