	public void Evt_TriggerNormalDamageEffect_Invoke(AActor Attacker, FSkillDamageConfig SkillDamageConfig, FEffectInstReq EffectInstReq, FBattleAttrSnapShot Attacker_AttrMemData)
	{
		if (base.HasAuthority)
		{
			Evt_TriggerNormalDamageEffectMultiCast(Attacker, SkillDamageConfig, EffectInstReq, Attacker_AttrMemData);
			return;
		}
		GSPredictionKey gSPredictionKey = null;
		int predictionKeyId = -1;
		int parentPredictionKeyId = -1;
		if (PredictionKeyData.ServerRecvingOrClientCueing())
		{
			return;
		}
		APawn controlledPawn = UGSE_EngineFuncLib.GetFirstLocalPlayerController(GetOwner()).GetControlledPawn();
		BGUPlayerCharacterCS bGUPlayerCharacterCS = GetOwner() as BGUPlayerCharacterCS;
		if (base.IsServer || !(bGUPlayerCharacterCS != null) || !(bGUPlayerCharacterCS != controlledPawn))
		{
			gSPredictionKey = BGS_EventCollectionCS.Get(GetOwner())?.Evt_BGS_AllocPredictionKey.Invoke();
			if (gSPredictionKey != null)
			{
				predictionKeyId = gSPredictionKey.Id;
				parentPredictionKeyId = gSPredictionKey.ParentId;
			}
			BGS_EventCollectionCS.Get(GetOwner())?.Evt_BGS_BeginPredictionScope.Invoke(EPredictionState.ClientPredicting, BGC_PredictionKeyData.sPredictableFunctionCache["BUS_GSEventCollection:Evt_TriggerNormalDamageEffectMultiCast"], gSPredictionKey.Id);
			Evt_TriggerNormalDamageEffect.PredictInvoke(Attacker, SkillDamageConfig, EffectInstReq, Attacker_AttrMemData, gSPredictionKey);
			BGS_EventCollectionCS.Get(GetOwner())?.Evt_BGS_EndPredictionScope.Invoke();
			if (controlledPawn == GetOwner())
			{
				Evt_TriggerNormalDamageEffectServer(Attacker, SkillDamageConfig, EffectInstReq, Attacker_AttrMemData, predictionKeyId, parentPredictionKeyId);
			}
			else if (base.IsServer)
			{
				Evt_TriggerNormalDamageEffectSPTransmitServer(Attacker, SkillDamageConfig, EffectInstReq, Attacker_AttrMemData, predictionKeyId, parentPredictionKeyId, UGSE_EngineFuncLib.GetFirstLocalPlayerController(GetOwner()).PlayerState);
			}
			else if (controlledPawn != null)
			{
				BUS_EventCollectionCS.Get(controlledPawn)?.Evt_TriggerNormalDamageEffectSPTransmitServer(Attacker, SkillDamageConfig, EffectInstReq, Attacker_AttrMemData, predictionKeyId, parentPredictionKeyId, GetOwner());
			}
		}
	}

